// Existing build info functions
public native @Cast("const char*") BytePointer buildInfo();
// Single-line canonical form of buildInfo() for cache fingerprinting.
// buildInfo() is a multi-line human-readable report; line-oriented consumers
// (key=value sidecar files like the DSP plan cache .meta) truncate multi-line
// values on read, so fingerprints MUST use this form. Canonicalization:
// every '\n'/'\r' becomes a single space, leading/trailing whitespace trimmed
// (byte-identical to the Java-side fallback in DspPlanDiskCache).
public native @Cast("const char*") BytePointer buildInfoFingerprint();
public native @Cast("bool") boolean isFuncTrace();

// Type information functions
public native @Cast("const char*") BytePointer getSupportedTypes();
public native @Cast("const char**") PointerPointer getSupportedTypesArray();
public native int getSupportedTypesCount();
public native @Cast("bool") boolean isTypeSupported(@Cast("const char*") BytePointer typeName);
public native @Cast("bool") boolean isTypeSupported(String typeName);

// Type metadata functions
public native @Cast("bool") boolean hasSelectiveTypes();
public native @Cast("const char*") BytePointer getTypeSelectionMode();
public native @Cast("const char*") BytePointer getBinaryTypeInfo();

public native @Cast("const char*") BytePointer getMissingTypeError(@Cast("const char*") BytePointer missingType, @Cast("const char*") BytePointer context);
public native String getMissingTypeError(String missingType, String context);
public native @Cast("const char*") BytePointer getDetailedTypeConfig();

// #ifdef __cplusplus

