public native @StdString String generateMissingTypeError(@StdString String missingType, @StdString String context/*=""*/);
public native @StdString String generateMissingTypeError(@StdString String missingType);

// Generate error message for operations with missing types
// Generate error message for operations with missing types
public native @StdString BytePointer generateTypeMismatchError(@StdString BytePointer operation,
                                      @StdString @StdVector BytePointer requiredTypes,
                                      @StdString BytePointer context/*=""*/);
